"""Regenerates src/lib/lessons/tutor.ts from scripts/tutor-levels.json.

tutor-levels.json is the lesson list the Tek Gear Typing Tutor serves at
https://tutor.mytwiddler.com/tutor2/level (read on 21 November 2026).
Run from the repository root: python3 scripts/lessons.py
"""

import json
import re

HEADER = '''// The lessons of the Tek Gear Typing Tutor (tutor.mytwiddler.com/tutor2), read on 21 November 2026:
// 69 lessons in three stages. Runs of spaces are collapsed to one and the ends trimmed; the text is
// otherwise as published. Generated by scripts/lessons.py; do not edit by hand.

export interface TutorLesson {
  /** Lesson number, 1 to 69, as the tutor numbers them. */
  n: number;
  /** The tutor's stage name. */
  stage: string;
  /** The text to type. */
  text: string;
}

export const TUTOR_LESSONS: TutorLesson[] = '''

levels = sorted(json.load(open('scripts/tutor-levels.json')), key=lambda x: x['level'])
out = [{'n': x['level'], 'stage': x['typename'], 'text': re.sub(r'\s+', ' ', x['lessonstring']).strip()} for x in levels if x['visible']]
open('src/lib/lessons/tutor.ts', 'w').write(HEADER + json.dumps(out, ensure_ascii=False, indent=2) + ';\n')
print(len(out), 'lessons')
